INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter Business Process Management (BPM)?', 2, '[{"text": "Verwaltung und Optimierung von Geschäftsprozessen", "correct": true, "because": "Automatisierung und Effizienz"}, {"text": "Hardwarewartung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit BPM?', 3, '[{"text": "Effizienz von Prozessen steigern", "correct": true, "because": "Optimierung"}, {"text": "Kosten direkt senken", "correct": false, "because": "Indirekt"}, {"text": "Design verbessern", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu BPM?', 5, '[{"text": "Prozessmodellierung", "correct": true, "because": "Darstellung"}, {"text": "Automatisierung", "correct": true, "because": "Softwareunterstützung"}, {"text": "Büroverschönerung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) BPM optimiert Geschäftsprozesse. b) Es ist nur für große Unternehmen geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch kleine Firmen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei BPM?', 4, '[{"text": "Prozessdefinition", "correct": false, "because": "Grundlage"}, {"text": "Automatisierungstools", "correct": false, "because": "Wichtig"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob BPM Softwaretools nutzt?', 2, '[{"text": "Ja", "correct": true, "because": "Automatisierung"}, {"text": "Nein", "correct": false, "because": "Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wird oft für BPM verwendet?', 3, '[{"text": "Camunda", "correct": true, "because": "Prozessmanagement"}, {"text": "Photoshop", "correct": false, "because": "Grafiktool"}, {"text": "Excel", "correct": false, "because": "Tabellenkalkulation"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Umsetzung von BPM?', 5, '[{"text": "Prozessanalyse", "correct": true, "because": "Optimierungspotenzial"}, {"text": "Workflow-Design", "correct": true, "because": "Abläufe gestalten"}, {"text": "Farbcodierung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) BPM verbessert Effizienz. b) Es ist nur für Hardware relevant. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Softwareprozesse"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei BPM unwichtig?', 4, '[{"text": "Prozessmodellierung", "correct": false, "because": "Kern"}, {"text": "Automatisierung", "correct": false, "because": "Hauptaspekt"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss BPM Prozesse dokumentieren?', 2, '[{"text": "Ja", "correct": true, "because": "Nachvollziehbarkeit"}, {"text": "Nein", "correct": false, "because": "Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet BPM für Fachinformatiker?', 4, '[{"text": "Effizienzsteigerung", "correct": true, "because": "Prozessoptimierung"}, {"text": "Transparenz", "correct": true, "because": "Dokumentation"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass BPM nur für große Firmen ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Unternehmen"}, {"text": "Ja", "correct": false, "because": "Universell"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei BPM?', 3, '[{"text": "Prozessoptimierung", "correct": true, "because": "Hauptziel"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) BPM nutzt Prozessmodellierung. b) Es ist nur für Hardwareprozesse geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Software"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat BPM?', 5, '[{"text": "Hoher Einführungsaufwand", "correct": true, "because": "Komplexität"}, {"text": "Zeitaufwendige Modellierung", "correct": true, "because": "Dokumentation"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker bei BPM?', 3, '[{"text": "Prozesse modellieren", "correct": true, "because": "Optimierung"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann BPM automatisiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Tools wie Camunda"}, {"text": "Nein", "correct": false, "because": "Automatisierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool könnte ein Fachinformatiker für BPM nutzen?', 4, '[{"text": "Bizagi", "correct": true, "because": "Prozessmanagement"}, {"text": "Photoshop", "correct": false, "because": "Grafiktool"}, {"text": "Excel", "correct": false, "because": "Tabellenkalkulation"}]');
